package java.util;
import java.util.function.*;
public final class OptionalLong {private static final OptionalLong EMPTY=new OptionalLong();private final boolean present;private final long value;private OptionalLong(){present=false;value=0;}private OptionalLong(long v){present=true;value=v;}public static OptionalLong empty(){return EMPTY;}public static OptionalLong of(long v){return new OptionalLong(v);}public long getAsLong(){if(!present)throw new NoSuchElementException("No value present");return value;}public boolean isPresent(){return present;}public void ifPresent(LongConsumer c){if(present)c.accept(value);}public long orElse(long other){return present?value:other;}public long orElseGet(LongSupplier s){return present?value:s.getAsLong();}public <X extends Throwable> long orElseThrow(Supplier<? extends X> s) throws X{if(present)return value;throw s.get();}public boolean equals(Object o){if(!(o instanceof OptionalLong))return false;OptionalLong x=(OptionalLong)o;return present==x.present&&(!present||value==x.value);}public int hashCode(){return present?Long.hashCode(value):0;}public String toString(){return present?"OptionalLong["+value+"]":"OptionalLong.empty";}}
